FROM #cst_lease_values

SELECT *
FROM countyScansTitle_Training.dbo.tblrecord tr
JOIN countyScansTitle_Training.dbo.tblexportlog tel ON tel.recordid = tr.recordid
WHERE tel.LeaseID IN (SELECT lease_id FROM #cst_lease_values)

SELECT *
FROM countyScansTitle_Training.dbo.tblexportLog
WHERE LeaseID = 47596


