SET XACT_ABORT ON;
BEGIN TRAN;

SELECT statusID, COUNT(*)
FROM countyScansTitle.dbo.tblrecord tr
JOIN countyScansTitle.dbo.tblexportlog tel ON tel.recordid = tr.recordid
WHERE tr.recordID IN (SELECT record_id FROM #cst_recordid_values)
GROUP BY statusID

UPDATE countyScansTitle.dbo.tblrecord
SET statusID = 4
WHERE recordID IN (SELECT record_id FROM #cst_recordid_values)

SELECT statusID, COUNT(*)
FROM countyScansTitle.dbo.tblrecord tr
JOIN countyScansTitle.dbo.tblexportlog tel ON tel.recordid = tr.recordid
WHERE tr.recordID IN (SELECT record_id FROM #cst_recordid_values)
GROUP BY statusID

-- Rollback the transaction (for testing purposes)
--ROLLBACK TRAN;
-- Uncomment the following line to commit the transaction
COMMIT TRAN;

-- Check transaction count and state
SELECT @@TRANCOUNT, XACT_STATE();

-- Swap to Prod and you can update all the records to statusid = 4 using the temporary table